import { useState, type HTMLAttributes, type ReactNode, type Ref } from 'react';
import { cn } from '../../utils/cn';
import { NavList, type NavGroup, type NavItem } from '../../ui/nav-list';
import { navItemKey } from '../../ui/nav-list/nav-context';
import { SimpleSelect } from '../../ui/select';
import { SkipLink } from '../../ui/visually-hidden';
import { useI18n } from '../../i18n/I18nProvider';
import { settingsLayoutVariants, type SettingsLayoutVariantProps } from './settings-layout.variants';

/** Every selectable (leaf) item, depth-first. */
function flattenLeaves(items: NavItem[]): NavItem[] {
  return items.flatMap((item) => (item.items?.length ? flattenLeaves(item.items) : [item]));
}

function markCurrent(items: NavItem[], value: string | undefined): NavItem[] {
  return items.map((item) =>
    item.items?.length ? { ...item, items: markCurrent(item.items, value) } : { ...item, current: item.current ?? navItemKey(item) === value },
  );
}

export interface SettingsLayoutProps extends Omit<HTMLAttributes<HTMLDivElement>, 'className' | 'title' | 'defaultValue'> {
  className?: string;
  ref?: Ref<HTMLDivElement>;
  /** Section navigation (NavList groups). Items are keyed by `id`, then `href`, then `label`. */
  groups: NavGroup[];
  /** Key of the current section (controlled). */
  value?: string;
  /** Initial section (uncontrolled). Defaults to the first item. */
  defaultValue?: string;
  /** Called when a section is chosen from the nav or the small-screen Select. Route here for `href` sections. */
  onValueChange?: (value: string, item: NavItem) => void;
  /** Heading above the section nav and accessible name of the nav. */
  navLabel?: string;
  /** Page title (an `<h1>`). */
  title?: ReactNode;
  description?: ReactNode;
  /** Replaces the default title block. */
  header?: ReactNode;
  /** Form sections of the current page. */
  children?: ReactNode;
  /** Sticky bar at the bottom of the content (Discard · Save changes). */
  saveBar?: ReactNode;
  /** Max width of the content column. */
  width?: SettingsLayoutVariantProps['width'];
  /**
   * Inside an app shell that already owns <main> and the skip link (SidebarLayout, StackedLayout):
   * render the content region as a plain <div> and drop this layout's skip link.
   */
  embedded?: boolean;
  /** Label of the small-screen section Select. */
  selectLabel?: string;
  mainId?: string;
  skipLinkLabel?: string;
  fullScreen?: boolean;
}

/**
 * Settings shell: section nav (NavList) on the left · content with form sections · sticky save bar.
 * Below `lg` the nav becomes a Select at the top of the page. The current section is
 * controllable (`value` / `onValueChange`).
 */
export function SettingsLayout({
  groups,
  value: valueProp,
  defaultValue,
  onValueChange,
  navLabel: navLabelProp,
  title,
  description,
  header,
  children,
  saveBar,
  width,
  selectLabel: selectLabelProp,
  embedded = false,
  mainId = 'main',
  skipLinkLabel: skipLinkLabelProp,
  fullScreen = false,
  className,
  ...props
}: SettingsLayoutProps) {
  const { t } = useI18n();
  const navLabel = navLabelProp ?? t('common.settings');
  const selectLabel = selectLabelProp ?? t('settings.section');
  const skipLinkLabel = skipLinkLabelProp ?? t('skip.content');
  const MainTag = embedded ? 'div' : 'main';
  const leaves = groups.flatMap((g) => flattenLeaves(g.items));
  const firstKey = leaves[0] ? navItemKey(leaves[0]) : undefined;
  const [inner, setInner] = useState(defaultValue ?? firstKey);
  const value = valueProp ?? inner;
  const s = settingsLayoutVariants({ width, fullScreen });

  const select = (key: string, item: NavItem) => {
    if (valueProp === undefined) setInner(key);
    onValueChange?.(key, item);
  };
  const marked = groups.map((g) => ({ ...g, items: markCurrent(g.items, value) }));
  const options = leaves.filter((i) => !i.disabled).map((i) => ({ value: navItemKey(i), label: i.label }));

  return (
    <div className={cn(s.root(), className)} {...props}>
      {!embedded && (
        <SkipLink targetId={mainId} className={s.skipLink()}>
          {skipLinkLabel}
        </SkipLink>
      )}
      <div className={s.sidebar()}>
        <p className={s.sidebarHeading()} aria-hidden>
          {navLabel}
        </p>
        <NavList label={navLabel} groups={marked} onNavigate={(item) => select(navItemKey(item), item)} />
      </div>
      <div className={s.compactNav()}>
        <SimpleSelect
          aria-label={selectLabel}
          items={options}
          value={value ?? null}
          onValueChange={(key) => {
            const item = leaves.find((i) => navItemKey(i) === key);
            if (key != null && item) select(key, item);
          }}
          className="w-full"
        />
      </div>
      <MainTag id={mainId} tabIndex={-1} className={s.main()}>
        <div className={s.content()}>
          {header ??
            (title != null && (
              <div className={s.header()}>
                <h1 className={s.title()}>{title}</h1>
                {description != null && <p className={s.description()}>{description}</p>}
              </div>
            ))}
          {children}
        </div>
        {saveBar != null && <div className={s.saveBar()}>{saveBar}</div>}
      </MainTag>
    </div>
  );
}

export { SettingsLayout, type SettingsLayoutProps } from './SettingsLayout';
export { settingsLayoutVariants, type SettingsLayoutVariantProps } from './settings-layout.variants';
export { doc as settingsLayoutDoc } from './SettingsLayout.doc';

import { tv, type VariantProps } from '../../utils/tv';

export const settingsLayoutVariants = tv({
  slots: {
    root: 'relative flex flex-col overflow-hidden bg-background font-sans text-foreground lg:flex-row',
    skipLink: 'focus:absolute',
    sidebar: 'hidden w-60 shrink-0 flex-col gap-4 overflow-y-auto border-e border-border bg-background px-3 py-6 lg:flex',
    sidebarHeading: 'px-2.5 text-[13px] font-semibold tracking-tight text-foreground',
    compactNav: 'shrink-0 border-b border-border px-4 py-3 lg:hidden',
    main: 'flex min-h-0 min-w-0 flex-1 flex-col overflow-y-auto outline-none',
    content: 'mx-auto flex w-full flex-1 flex-col gap-8 px-4 py-6 sm:px-8 lg:py-8',
    header: 'flex flex-col gap-1 border-b border-border pb-5',
    title: 'text-[20px] font-semibold tracking-tight text-foreground',
    description: 'text-[13px] leading-relaxed text-muted-foreground',
    saveBar: [
      'sticky bottom-0 z-10 mt-auto border-t border-border bg-card/95 shadow-sm',
      'flex items-center justify-end gap-2 px-4 py-3 sm:px-8',
    ],
  },
  variants: {
    width: {
      narrow: { content: 'max-w-2xl' },
      default: { content: 'max-w-3xl' },
      wide: { content: 'max-w-5xl' },
    },
    fullScreen: {
      true: { root: 'h-dvh' },
      false: { root: 'h-full min-h-full' },
    },
  },
  defaultVariants: { width: 'default', fullScreen: false },
});

export type SettingsLayoutVariantProps = VariantProps<typeof settingsLayoutVariants>;

import type { ComponentDoc } from '../../doc';

export const doc: ComponentDoc = {
  name: 'SettingsLayout',
  group: 'Layout',
  status: 'beta',
  description:
    'Settings shell: section nav (NavList groups) on the left · a content column with the page title and form sections · a sticky save bar slot (Discard · Save changes). The current section is controllable with `value` / `onValueChange`; `href` items navigate as links and still report the change. Below `lg` the nav becomes a Select at the top of the page. Fills its container; `fullScreen` switches to `h-dvh`.',
  primitive: '@base-ui/react/select (small screens)',
  pattern: 'landmarks (labelled nav, main) + select-only combobox on small screens',
  keyboard: [
    ['Tab', 'Skip link, then the section nav items, then the content and the save bar'],
    ['Enter', 'Opens the focused section (aria-current="page" moves to it)'],
    ['Enter / Space / ↓ on the section Select', 'Small screens: opens the list; arrows move, Enter picks a section'],
  ],
  tokens: ['background', 'foreground', 'card', 'border', 'muted-foreground', 'primary', 'focus-ring'],
};
